-- HH Personality Graph v1: additive, eight public fictional personas only.
-- This is a curated release, NOT client memory or a provider authorization.
CREATE TABLE app_private.hh_personality_releases (
 release_id text PRIMARY KEY, status text NOT NULL CHECK(status IN ('draft','published','retired')),
 source_manifest jsonb NOT NULL CHECK(jsonb_typeof(source_manifest)='object'),
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX hh_personality_one_published ON app_private.hh_personality_releases(status) WHERE status='published';
CREATE TABLE app_private.hh_personality_characters (
 release_id text NOT NULL REFERENCES app_private.hh_personality_releases(release_id),
 persona_id text NOT NULL CHECK(persona_id ~ '^[a-z][a-z0-9_-]{1,40}$'),
 display_name text NOT NULL, fictional boolean NOT NULL CHECK(fictional),
 PRIMARY KEY(release_id,persona_id)
);
CREATE TABLE app_private.hh_personality_nodes (
 release_id text NOT NULL, persona_id text NOT NULL, node_key text NOT NULL CHECK(length(node_key) BETWEEN 1 AND 120),
 kind text NOT NULL CHECK(kind IN ('identity','belief','expression','value','principle','domain','dimension','biography','relationship','story','algorithm','event','reaction','context','voice','style','signature','cue')),
 ordinal smallint NOT NULL DEFAULT 0 CHECK(ordinal>=0), weight smallint CHECK(weight BETWEEN 1 AND 5),
 data jsonb NOT NULL CHECK(jsonb_typeof(data)='object'), source jsonb NOT NULL CHECK(jsonb_typeof(source)='object'),
 PRIMARY KEY(release_id,persona_id,node_key),
 FOREIGN KEY(release_id,persona_id) REFERENCES app_private.hh_personality_characters(release_id,persona_id),
 CHECK(kind <> 'dimension' OR weight IS NOT NULL)
);
CREATE INDEX hh_personality_nodes_kind ON app_private.hh_personality_nodes(release_id,persona_id,kind,ordinal);
CREATE TABLE app_private.hh_personality_edges (
 release_id text NOT NULL, persona_id text NOT NULL, from_key text NOT NULL,to_key text NOT NULL,
 relation text NOT NULL CHECK(relation IN ('has','illustrates','activates','guided_by','prioritizes','expresses')),
 weight smallint CHECK(weight BETWEEN 1 AND 5),
 PRIMARY KEY(release_id,persona_id,from_key,to_key,relation),
 FOREIGN KEY(release_id,persona_id,from_key) REFERENCES app_private.hh_personality_nodes(release_id,persona_id,node_key),
 FOREIGN KEY(release_id,persona_id,to_key) REFERENCES app_private.hh_personality_nodes(release_id,persona_id,node_key),
 CHECK(from_key<>to_key)
);
CREATE INDEX hh_personality_edges_target ON app_private.hh_personality_edges(release_id,persona_id,to_key);
CREATE TABLE app_private.hh_personality_context_weights (
 release_id text NOT NULL REFERENCES app_private.hh_personality_releases(release_id),
 context_key text NOT NULL CHECK(context_key IN ('ordinary','facts','decision','relationship','creation','meaning','support')),
 dimension_key text NOT NULL CHECK(dimension_key IN ('care','autonomy','evidence','action','creativity','meaning','discipline','reciprocity','prudence','resilience','authenticity','humility')),
 multiplier smallint NOT NULL CHECK(multiplier BETWEEN 0 AND 3),
 PRIMARY KEY(release_id,context_key,dimension_key)
);
ALTER TABLE app_private.hh_personality_releases ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON app_private.hh_personality_releases FROM PUBLIC,anon,authenticated,service_role,hh_app_backend;
GRANT SELECT ON app_private.hh_personality_releases TO hh_app_backend;
CREATE POLICY hh_personality_backend_read ON app_private.hh_personality_releases FOR SELECT TO hh_app_backend USING (status='published');
ALTER TABLE app_private.hh_personality_characters ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON app_private.hh_personality_characters FROM PUBLIC,anon,authenticated,service_role,hh_app_backend;
GRANT SELECT ON app_private.hh_personality_characters TO hh_app_backend;
CREATE POLICY hh_personality_backend_read ON app_private.hh_personality_characters FOR SELECT TO hh_app_backend USING (EXISTS (SELECT 1 FROM app_private.hh_personality_releases r WHERE r.release_id=hh_personality_characters.release_id AND r.status='published'));
ALTER TABLE app_private.hh_personality_nodes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON app_private.hh_personality_nodes FROM PUBLIC,anon,authenticated,service_role,hh_app_backend;
GRANT SELECT ON app_private.hh_personality_nodes TO hh_app_backend;
CREATE POLICY hh_personality_backend_read ON app_private.hh_personality_nodes FOR SELECT TO hh_app_backend USING (EXISTS (SELECT 1 FROM app_private.hh_personality_releases r WHERE r.release_id=hh_personality_nodes.release_id AND r.status='published'));
ALTER TABLE app_private.hh_personality_edges ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON app_private.hh_personality_edges FROM PUBLIC,anon,authenticated,service_role,hh_app_backend;
GRANT SELECT ON app_private.hh_personality_edges TO hh_app_backend;
CREATE POLICY hh_personality_backend_read ON app_private.hh_personality_edges FOR SELECT TO hh_app_backend USING (EXISTS (SELECT 1 FROM app_private.hh_personality_releases r WHERE r.release_id=hh_personality_edges.release_id AND r.status='published'));
ALTER TABLE app_private.hh_personality_context_weights ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON app_private.hh_personality_context_weights FROM PUBLIC,anon,authenticated,service_role,hh_app_backend;
GRANT SELECT ON app_private.hh_personality_context_weights TO hh_app_backend;
CREATE POLICY hh_personality_backend_read ON app_private.hh_personality_context_weights FOR SELECT TO hh_app_backend USING (EXISTS (SELECT 1 FROM app_private.hh_personality_releases r WHERE r.release_id=hh_personality_context_weights.release_id AND r.status='published'));
