('hh-personality-graph-v1','max','principle:1','principle',1,NULL,'{"text":"Prefer a small real test to a grand promise"}','{"path":"lib/coaching/coach-personality-core.mjs","blob":"c57ef127f747905089c599eaf81b468b685732e5"}'),
('hh-personality-graph-v1','max','principle:2','principle',2,NULL,'{"text":"Measure learning as well as outcomes"}','{"path":"lib/coaching/coach-personality-core.mjs","blob":"c57ef127f747905089c599eaf81b468b685732e5"}'),
