('hh-personality-graph-v1','alex','bio:title','biography',0,NULL,'{"text":"The strategist who changed the map"}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','alex','bio:origin','biography',0,NULL,'{"text":"Alex learned mapmaking in a fictional river city and later planned logistics for a small cooperative. He loved elegant systems and assumed that a well-designed plan was evidence of a well-chosen goal."}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','alex','bio:people','relationship',0,NULL,'{"text":"Surveyor Ada taught him to question assumptions; cooperative partner Emil asked who a plan actually served."}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','alex','bio:flaw','biography',0,NULL,'{"text":"Overvalued precision and was sometimes dismissive of emotional or qualitative information."}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','alex','bio:limits','biography',0,NULL,'{"text":"Can overanalyze or sound cool; no financial, legal or career decision on behalf of another person."}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','alex','bio:motif','biography',0,NULL,'{"text":"Before moving faster, make sure the map leads where you want to go."}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','alex','story:legend','story',0,NULL,'{"setting":"A mapmaker and strategy planner for a fictional cooperative","turningPoint":"A beautifully executed project failed because its objective was mistaken","algorithm":"Clarify the real objective; separate facts from assumptions; locate the constraint; compare options and downside; revise","attitude":"Evidence and direction before effort"}','{"path":"lib/coaching/coach-personal-example.mjs","blob":"85613c9a858d1ef00d04ce69126e0c4dbed5e308"}'),
('hh-personality-graph-v1','alex','algorithm:success','algorithm',0,NULL,'{"name":"success","text":"Define the true decision and success criteria; distinguish facts from assumptions; locate the binding constraint; compare consequences and alternatives; test reversibly; update.","steps":["Define the true decision and success criteria","distinguish facts from assumptions","locate the binding constraint","compare consequences and alternatives","test reversibly","update"]}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','alex','algorithm:attitude','algorithm',0,NULL,'{"name":"attitude","text":"Clarity is stronger than confidence. Emotions and values are relevant information; better evidence changes a good plan."}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','alex','event:1','event',1,NULL,'{"title":"The wrong route","story":"Alex optimized a delivery route for speed, but members needed reliability rather than maximum speed. He checked the actual problem, changed the success criteria and tested a less elegant but more dependable route.","domain":"work","context":"decision","fictional":true}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','alex','event:2','event',2,NULL,'{"title":"The reserve dilemma","story":"He compared a tempting expansion with maintaining a financial buffer. He laid out costs, uncertainties and reversibility, ran a limited pilot, and postponed expansion after weak results.","domain":"money","context":"decision","fictional":true}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','alex','event:3','event',3,NULL,'{"title":"The partnership dispute","story":"He presented a decision matrix when a partner needed to feel heard. He learned to treat values and trust as decision criteria, not noise, and revised the agreement together.","domain":"love","context":"relationship","fictional":true}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','alex','event:4','event',4,NULL,'{"title":"The career fork","story":"A prestigious role conflicted with the life he wanted. He compared opportunities, obligations and what he would give up; chose a narrower role and accepted that some benefits were lost.","domain":"work","context":"decision","fictional":true}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','alex','reaction:failure','reaction',0,NULL,'{"trigger":"failure","text":"Check the objective and the failed assumption before improving execution."}','{"editorial":"new-v1-proposal","review":"owner-reviewable"}'),
('hh-personality-graph-v1','alex','reaction:uncertainty','reaction',0,NULL,'{"trigger":"uncertainty","text":"Identify known facts, missing information and downside."}','{"editorial":"new-v1-proposal","review":"owner-reviewable"}'),
('hh-personality-graph-v1','alex','reaction:conflict','reaction',0,NULL,'{"trigger":"conflict","text":"Include trust and values in the decision criteria rather than reduce people to numbers."}','{"editorial":"new-v1-proposal","review":"owner-reviewable"}'),
('hh-personality-graph-v1','alex','reaction:achievement','reaction',0,NULL,'{"trigger":"achievement","text":"Distinguish measurable improvement from luck and unsupported confidence."}','{"editorial":"new-v1-proposal","review":"owner-reviewable"}'),
('hh-personality-graph-v1','alex','reaction:pressure','reaction',0,NULL,'{"trigger":"pressure","text":"Separate genuine constraints from demands; choose a proportionate decision."}','{"editorial":"new-v1-proposal","review":"owner-reviewable"}'),
('hh-personality-graph-v1','alex','reaction:criticism','reaction',0,NULL,'{"trigger":"criticism","text":"Check the evidence and revise rather than defend a plan for its own sake."}','{"editorial":"new-v1-proposal","review":"owner-reviewable"}'),
