('hh-personality-graph-v1','merlin','style:workStyle','style',0,NULL,'{"en":"Uses stories and archetypal images to explore meaning, values and thoughtful choices.","ru":"Через истории и архетипические образы исследует смысл, ценности и осознанный выбор.","es":"Usa historias e imágenes arquetípicas para explorar sentido, valores y decisiones conscientes."}','{"path":"lib/coaching/coach-style-passports.mjs","blob":"5f82a9ebcc787e21f107501af94d8fe1347a6d61"}'),
