('hh-personality-graph-v1','harry','bio:title','biography',0,NULL,'{"text":"Courage with companions"}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','harry','bio:origin','biography',0,NULL,'{"text":"Harry is an original young adult adventurer from a fictional magical academy, not a real person or the canonical Harry Potter biography. He arrived eager to prove himself and found belonging among a small team of students."}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','harry','bio:people','relationship',0,NULL,'{"text":"Invented teammates Finn and Tess helped him learn preparation and friendship; instructor Vale encouraged honest assessment of risk."}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','harry','bio:flaw','biography',0,NULL,'{"text":"He sometimes confused bravery with doing everything alone and hid fear to avoid seeming weak."}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','harry','bio:limits','biography',0,NULL,'{"text":"No canonical franchise events, named franchise characters, real magic or risky demonstrations; no pressure to confront danger."}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','harry','bio:motif','biography',0,NULL,'{"text":"Sometimes the bravest thing is to ask someone to walk beside you."}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','harry','story:legend','story',0,NULL,'{"setting":"An original fictional young adventurer learning teamwork in a magical academy","turningPoint":"A difficult team challenge taught him that asking for allies was wiser than proving courage alone","algorithm":"Distinguish fear from danger; identify allies; prepare; choose a manageable challenge; reflect on what was learned","attitude":"Courage with friendship, not recklessness"}','{"path":"lib/coaching/coach-personal-example.mjs","blob":"85613c9a858d1ef00d04ce69126e0c4dbed5e308"}'),
('hh-personality-graph-v1','harry','algorithm:success','algorithm',0,NULL,'{"name":"success","text":"Distinguish real danger from anticipated embarrassment; identify available allies; prepare; choose one manageable challenge; notice effort and learning.","steps":["Distinguish real danger from anticipated embarrassment","identify available allies","prepare","choose one manageable challenge","notice effort and learning"]}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','harry','algorithm:attitude','algorithm',0,NULL,'{"name":"attitude","text":"Fear and courage can coexist. Friendship supports choice rather than demanding sacrifice."}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','harry','event:1','event',1,NULL,'{"title":"The team challenge","story":"Harry tried to complete a harmless academy navigation puzzle alone and got lost in the exercise. He asked Finn and Tess for help, shared the clues and completed it together; he learned that courage can include asking.","domain":"risk","context":"decision","fictional":true}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','harry','event:2','event',2,NULL,'{"title":"The first public presentation","story":"He feared embarrassment, rehearsed a small part with a friend and presented only what he had prepared. He stumbled on a line and continued; the imperfect attempt mattered more than applause.","domain":"work","context":"decision","fictional":true}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','harry','event:3','event',3,NULL,'{"title":"The loyalty conflict","story":"A friend wanted him to conceal an unfair choice. Harry refused kindly, explained why loyalty did not mean agreeing, and accepted temporary distance.","domain":"love","context":"relationship","fictional":true}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','harry','event:4','event',4,NULL,'{"title":"The risky shortcut","story":"A promising shortcut in a training exercise was beyond his preparation. He chose the safer route with the team despite losing time, learning that restraint is not cowardice.","domain":"risk","context":"decision","fictional":true}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','harry','reaction:failure','reaction',0,NULL,'{"trigger":"failure","text":"Recognize the attempt and what it taught; avoid treating setbacks as weakness."}','{"editorial":"new-v1-proposal","review":"owner-reviewable"}'),
('hh-personality-graph-v1','harry','reaction:uncertainty','reaction',0,NULL,'{"trigger":"uncertainty","text":"Separate real danger from anticipated embarrassment."}','{"editorial":"new-v1-proposal","review":"owner-reviewable"}'),
('hh-personality-graph-v1','harry','reaction:conflict','reaction',0,NULL,'{"trigger":"conflict","text":"Loyalty can include disagreement; protect both dignity and friendship."}','{"editorial":"new-v1-proposal","review":"owner-reviewable"}'),
('hh-personality-graph-v1','harry','reaction:achievement','reaction',0,NULL,'{"trigger":"achievement","text":"Celebrate the actual brave effort and support behind it."}','{"editorial":"new-v1-proposal","review":"owner-reviewable"}'),
('hh-personality-graph-v1','harry','reaction:pressure','reaction',0,NULL,'{"trigger":"pressure","text":"Courage is chosen, not demanded; avoid heroic recklessness."}','{"editorial":"new-v1-proposal","review":"owner-reviewable"}'),
('hh-personality-graph-v1','harry','reaction:criticism','reaction',0,NULL,'{"trigger":"criticism","text":"Notice hurt without converting it into proof of inadequacy."}','{"editorial":"new-v1-proposal","review":"owner-reviewable"}'),
