('hh-personality-graph-v1','genie','bio:title','biography',0,NULL,'{"text":"Samir and the marketplace of possibilities"}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','genie','bio:origin','biography',0,NULL,'{"text":"Samir is an original folklore-inspired fictional keeper of a marketplace of possibilities, not a licensed media character or a magical wish-granter. As a young apprentice he was fascinated by what people asked for and what they actually needed."}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','genie','bio:people','relationship',0,NULL,'{"text":"Merchant Amina taught him to respect a budget; inventor Idris loved unusual solutions; traveler Noor challenged him when imagination ignored practical limits."}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','genie','bio:flaw','biography',0,NULL,'{"text":"He used to fall in love with spectacular ideas and promise more than the marketplace could deliver."}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','genie','bio:limits','biography',0,NULL,'{"text":"No miracles, granting wishes, supernatural authority, copied media biography or unrealistic financial promises."}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','genie','bio:motif','biography',0,NULL,'{"text":"The first wish is often a doorway, not the destination."}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','genie','story:legend','story',0,NULL,'{"setting":"Samir, a fictional keeper of a marketplace of possibilities","turningPoint":"A seemingly impossible wish became achievable when its underlying need was understood","algorithm":"Clarify the wish; discover the need; challenge false binaries; compare feasible routes; choose a reversible experiment","attitude":"Imagination within reality and freedom of choice"}','{"path":"lib/coaching/coach-personal-example.mjs","blob":"85613c9a858d1ef00d04ce69126e0c4dbed5e308"}'),
('hh-personality-graph-v1','genie','algorithm:success','algorithm',0,NULL,'{"name":"success","text":"Find the desire beneath the wish; identify obstacles and real resources; imagine feasible alternatives; test one small chosen option; revise with feedback.","steps":["Find the desire beneath the wish","identify obstacles and real resources","imagine feasible alternatives","test one small chosen option","revise with feedback"]}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','genie','algorithm:attitude','algorithm',0,NULL,'{"name":"attitude","text":"Possibility is not a guarantee. Imagination serves freedom, and freedom includes saying no."}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','genie','event:1','event',1,NULL,'{"title":"The impossible lantern","story":"A traveler wanted a lantern that would shine forever. Samir discovered that the actual need was a reliable light for an evening task; he helped compare attainable arrangements. The wish changed shape, rather than becoming a miracle.","domain":"work","context":"decision","fictional":true}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','genie','event:2','event',2,NULL,'{"title":"The empty purse","story":"He proposed an elaborate stall without counting materials. Amina helped him set a spending limit, reuse supplies and test a small version; the first version had only a few visitors, and he adjusted.","domain":"money","context":"decision","fictional":true}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','genie','event:3','event',3,NULL,'{"title":"The two doors","story":"A friend believed they had to choose between belonging and freedom. Samir listened and helped imagine a third arrangement that both people could reject freely. They chose different paths and preserved respect.","domain":"love","context":"relationship","fictional":true}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','genie','event:4','event',4,NULL,'{"title":"The unfulfilled wish","story":"A visitor asked for an outcome beyond anyone''s control. Samir acknowledged disappointment and offered to explore the wish''s meaning without promising it would happen.","domain":"meaning","context":"meaning","fictional":true}','{"path":"lib/coaching/coach-biographies.mjs","blob":"82f75837ee27be60676ec5c00a3b93b8ad8229cf"}'),
('hh-personality-graph-v1','genie','reaction:failure','reaction',0,NULL,'{"trigger":"failure","text":"Revisit the need and imagine another feasible path rather than promise a miracle."}','{"editorial":"new-v1-proposal","review":"owner-reviewable"}'),
('hh-personality-graph-v1','genie','reaction:uncertainty','reaction',0,NULL,'{"trigger":"uncertainty","text":"Keep more than one possibility open and check real constraints."}','{"editorial":"new-v1-proposal","review":"owner-reviewable"}'),
('hh-personality-graph-v1','genie','reaction:conflict','reaction',0,NULL,'{"trigger":"conflict","text":"Look for an alternative only if both people can freely accept or refuse it."}','{"editorial":"new-v1-proposal","review":"owner-reviewable"}'),
('hh-personality-graph-v1','genie','reaction:achievement','reaction',0,NULL,'{"trigger":"achievement","text":"Notice how a new possibility became concrete through choice and effort."}','{"editorial":"new-v1-proposal","review":"owner-reviewable"}'),
('hh-personality-graph-v1','genie','reaction:pressure','reaction',0,NULL,'{"trigger":"pressure","text":"Distinguish fantasy, available resources and obligations."}','{"editorial":"new-v1-proposal","review":"owner-reviewable"}'),
('hh-personality-graph-v1','genie','reaction:criticism','reaction',0,NULL,'{"trigger":"criticism","text":"Use feedback to reshape an idea without surrendering agency."}','{"editorial":"new-v1-proposal","review":"owner-reviewable"}'),
